using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EndTurnConditionPurifyOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EndTurnConditionPurifyOmenData")]
public class EndTurnConditionPurifyOmenData : EndTurnConditionOmenData
{
	[SerializeField]
	private PlayerPurifyOmenType playerPurifyOmenType;

	private Action<GameObject> omenAction;

	public override void InitializeCondition()
	{
		omenAction = delegate(GameObject target)
		{
			if (playerPurifyOmenType == PlayerPurifyOmenType.ENEMY)
			{
				if (ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(target))
				{
					ActivateOmen();
				}
			}
			else if (playerPurifyOmenType == PlayerPurifyOmenType.PLAYER && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(target))
			{
				ActivateOmen();
			}
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyWithTargetOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyWithTargetOmenActions.Remove(omenAction);
		base.OmenRemoved();
	}
}
